/* -------------------------------------------------- 纯解析函数 */

// ctx: { industry, serverMap, lang }
function getTerms(ctx) {
  const industry = (ctx && ctx.industry) || 'education';
  const base = TERM_DICT[industry] || TERM_DICT.education;
  if (!ctx || !ctx.serverMap) return base;
  return Object.assign({}, base, ctx.serverMap);
}

function termText(key, ctx) {
  if (!key) return '';
  const terms = getTerms(ctx);
  if (terms[key] != null && terms[key] !== '') return terms[key];
  if (TERM_DICT.education[key] != null) return TERM_DICT.education[key];
  return String(key);
}

function getOptions(tagKey, fallbackOptions, ctx) {
  const terms = getTerms(ctx);
  return (fallbackOptions || []).map(o => {
    const key = tagKey + '.' + (o.code != null ? o.code : o.value);
    return { value: o.value, text: (terms[key] != null && terms[key] !== '') ? terms[key] : (o.defaultText || o.value) };
  });
}

function normalizeCourseType(code) {
  if (code === null || code === undefined) return '';
  const s = String(code).trim();
  if (!s) return '';
  const low = s.toLowerCase();
  return COURSE_TYPE_ALIAS[low] || COURSE_TYPE_ALIAS[s] || low;
}

function courseTypeText(code, ctx) {
  const s = (code === null || code === undefined) ? '' : String(code).trim();
  if (!s) return '';
  const c = normalizeCourseType(s);
  const opt = COURSE_TYPE_OPTIONS.find(o => o.value === c);
  if (!opt) return s;
  return termText(opt.termKey, ctx);
}

function enumTermText(prefix, code, ctx) {
  const s = (code === null || code === undefined) ? '' : String(code).trim();
  if (!s) return '';
  const t = getTerms(ctx)[prefix + s];
  return (t != null && t !== '') ? t : s;
}

// shared/domain/refundRule.js
// 跨端共享「退改规则」领域层（纯逻辑，零 DOM / 零运行时 API 依赖）。
//
// 这是 P1（Headless 领域层下沉）的一部分：把原本混在 frontend/js/admin-refund-rule.js
// 里的分钟换算、三档判定、区间文案、规则校验、生效规则解析抽出来，让 Web 与小程
// 序共用同一份算法，UI 各自渲染。
//
// 生效顺序（业务语义）：课程专属规则 ＞ 租户默认规则 ＞ 系统内置兜底。
// 只有两个时间阈值，不退费区由「不足部分退费线」推导：
//   提前 ≥ 免责线              → 免责（退 100%）
//   部分退费线 ≤ 提前 < 免责线 → 部分退费（退 partialRefundPercent%）
//   提前 < 部分退费线          → 不退费（退 0%）
//
// 消费方式：
//   - 小程序端：import { evaluateRefund } from '../../shared/domain/refundRule.js'
//   - Web 端：经 P0 构建桥接挂到 window.RefundRuleDomain（见 PRD）
//   - Node 端：直接 require/import 做单测（本文件无任何 document/window/fetch 引用）

/* -------------------------------------------------- 内置兜底常量 */

// 系统内置默认：提前 24 小时免责 / 提前 12 小时退 50%
const REFUND_BUILT_IN_FALLBACK = Object.freeze({
  freeBeforeMinutes: 24 * 60,
  partialBeforeMinutes: 12 * 60,
  partialRefundPercent: 50,
  enabled: 1
});

/* -------------------------------------------------- 分钟 ↔ 粒度换算 */

/** 分钟数转可读文案：390 → "6 小时 30 分钟"；1440 → "24 小时"；1500 → "1 天 1 小时" */
function formatRefundMinutes(minutes) {
  if (minutes === null || minutes === undefined || minutes === '') return '-';
  const m = Number(minutes);
  if (isNaN(m)) return '-';
  if (m <= 0) return '0 分钟';
  const days = Math.floor(m / 1440);
  const rest = m % 1440;
  const hours = Math.floor(rest / 60);
  const mins = rest % 60;
  const parts = [];
  if (days > 0) parts.push(days + ' 天');
  if (hours > 0) parts.push(hours + ' 小时');
  if (mins > 0) parts.push(mins + ' 分钟');
  return parts.length ? parts.join(' ') : '0 分钟';
}

/** 按粒度把界面上的数值换算成分钟（hour→×60，minute→本身） */
function refundRuleToMinutes(value, unit) {
  const v = Number(value);
  if (isNaN(v) || v < 0) return NaN;
  return unit === 'minute' ? Math.round(v) : Math.round(v * 60);
}

/**
 * 分钟数回显成「数值 + 粒度」。
 * 优先沿用库里存的粒度；若按该粒度不能整除（如 90 分钟按小时就是 1.5），
 * 则退化为分钟显示，避免界面上出现 1.5 小时这种别扭的中间值。
 */
function refundRuleFromMinutes(minutes, unit) {
  const m = Number(minutes);
  if (isNaN(m) || m < 0) return { value: '', unit: unit || 'hour' };
  if (unit === 'minute') return { value: m, unit: 'minute' };
  if (m % 60 === 0) return { value: m / 60, unit: 'hour' };
  return { value: m, unit: 'minute' };
}

/* -------------------------------------------------- 三档区间文案 / 校验 */

/** 三档区间说明（纯前端拼，用于表单实时预览） */
function refundRuleZoneText(freeMinutes, partialMinutes, percent) {
  if (isNaN(freeMinutes) || isNaN(partialMinutes)) return '请先填写两个时间点';
  if (freeMinutes < partialMinutes) return '⚠ 免责时间点必须 ≥ 部分退费时间点';
  return '提前 ≥ ' + formatRefundMinutes(freeMinutes) + ' 免责（退 100%）　｜　'
    + formatRefundMinutes(partialMinutes) + ' ≤ 提前 < ' + formatRefundMinutes(freeMinutes)
    + ' 部分退费（退 ' + (percent === '' || isNaN(percent) ? '-' : percent) + '%）　｜　'
    + '提前 < ' + formatRefundMinutes(partialMinutes) + ' 不退费（退 0%）';
}

/**
 * 规则校验：返回 null 表示合法，否则返回错误文案（与 admin-refund-rule.js collectRefundRuleForm 的前端预校验保持一致）。
 * @param {number} freeMinutes       免责时间点（分钟）
 * @param {number} partialMinutes    部分退费时间点（分钟）
 * @param {number} percent           部分退费比例（%）
 */
function validateRefundRule(freeMinutes, partialMinutes, percent) {
  if (isNaN(freeMinutes) || freeMinutes === '') return '请填写免责时间点';
  if (isNaN(partialMinutes) || partialMinutes === '') return '请填写部分退费时间点';
  if (freeMinutes < partialMinutes) return '免责时间点必须大于或等于部分退费时间点';
  if (isNaN(percent) || percent < 1 || percent > 99) return '部分退费比例需在 1~99 之间';
  return null;
}

/* -------------------------------------------------- 生效规则解析 */

/**
 * 生效顺序解析：课程专属规则 ＞ 租户默认规则 ＞ 系统内置兜底。
 * 约定：有 id（非 null/undefined）视为「已保存的规则」；id 缺失视为「虚拟兜底项」不生效。
 * @param {Object|null} courseRule         课程专属规则（courseId 非空）
 * @param {Object|null} tenantDefaultRule  租户默认规则（courseId 为空串）
 * @returns {Object} 实际生效的规则对象
 */
function resolveEffectiveRule(courseRule, tenantDefaultRule) {
  if (courseRule && courseRule.id != null) return courseRule;
  if (tenantDefaultRule && tenantDefaultRule.id != null) return tenantDefaultRule;
  return REFUND_BUILT_IN_FALLBACK;
}

/* -------------------------------------------------- 核心：三档判定 */

/**
 * 计算某课次在给定时刻的退改档位（纯函数，零 DOM）。
 * 时间基准 = 课次的上课时间（appointmentTime）与操作时刻（now）的差值（提前多久）。
 *
 * @param {Object} rule 规则对象 { freeBeforeMinutes, partialBeforeMinutes, partialRefundPercent }
 * @param {Date|string|number} appointmentTime 课次上课时间（Date / ISO 字符串 / 时间戳）
 * @param {Date|string|number} [now]            操作时刻（默认 new Date()）
 * @returns {{ aheadMinutes:number, level:string, percent:number, levelText:string, aheadText:string }}
 *          level: 'free' 免责 | 'partial' 部分退费 | 'none' 不退费 | 'past' 已过期
 */
function evaluateRefund(rule, appointmentTime, now) {
  const appt = toDate(appointmentTime);
  const t = now == null ? new Date() : toDate(now);
  const aheadMinutes = Math.floor((appt.getTime() - t.getTime()) / 60000);

  let level, percent, levelText;
  if (aheadMinutes < 0) {
    level = 'past'; percent = 0; levelText = '已过期';
  } else if (aheadMinutes >= Number(rule.freeBeforeMinutes)) {
    level = 'free'; percent = 100; levelText = '免责';
  } else if (aheadMinutes >= Number(rule.partialBeforeMinutes)) {
    level = 'partial'; percent = Number(rule.partialRefundPercent); levelText = '部分退费';
  } else {
    level = 'none'; percent = 0; levelText = '不退费';
  }

  return {
    aheadMinutes,
    level,
    percent,
    levelText,
    aheadText: aheadMinutes < 0 ? '已过期' : formatRefundMinutes(aheadMinutes)
  };
}

/* -------------------------------------------------- 内部工具 */

function toDate(x) {
  if (x instanceof Date) return x;
  if (typeof x === 'number') return new Date(x);
  if (typeof x === 'string') {
    // 兼容 "2026-10-01 10:00"（后端部分接口用空格分隔）与标准 ISO "2026-10-01T10:00"
    const s = x.includes('T') || x.includes('Z') || x.includes('+') ? x : x.replace(' ', 'T');
    return new Date(s);
  }
  return new Date(x);
}

// shared/domain/bookingState.js
// 跨端共享「预约/排期状态机 + 候补满额判定」领域层（纯逻辑，零 DOM / 零运行时 API 依赖）。
//
// 这是 P1（Headless 领域层下沉）的一部分：把原本散落在
//   - frontend/js/public/courseAndBooking.js 的 bookingOccupiesSeat() / checkStatus_booking()
//   - frontend/js/student-bookingCards.js 的 formatRemainingSites() / FULLY_BOOKED_TEXT
//   - miniprogram/package-teacher/booking/booking.js 的 bkStatusText()
// 里的重复实现收口成唯一权威源，让 Web 与小程序共用同一套状态语义、占用口径、满额判定。
// UI 各自渲染（Decision 3：视图层允许不一致）。
//
// 【与后端同步】单一事实来源是 api/.../common/BookingStatus.java。
//   占席位态：booking(待确认) / booked(已确认) / canceling|canceling(取消申请在管理员确认前原预订仍有效)
//   非占位态：waiting(候补) / cancelled|canceled / rej-booking(预订被拒) / frozen|deleted(冻结/删除)
//   终态：    completed
//   后端存在美式/英式拼写（canceling/cancelling、canceled/cancelled），本模块统一归一。
//   并发安全（候补转正、取消）由后端闸门 857a233（排期行锁 + 锁定读计数 + CAS）保证，前端只做入口校验。
//
// 消费方式：
//   - 小程序端：import { bookingStatusText, bookingOccupiesSeat, formatRemainingSites } from '../../shared/domain/bookingState.js'
//   - Web 端：经构建桥接挂到 window.BookingStateDomain（P0-Web 已闭环；改本文件后需重跑
//     frontend/tools/gen-shared-bridge.js 才在浏览器生效，build.js 会自动调用）
//   - Node 端：直接 import 做单测（本文件无任何 document/window/fetch 引用）


/* -------------------------------------------------- 状态枚举（补全后端已知态） */

// 在 shared/constants.js 的 BOOKING_STATUS 基础上补全所有已知后端态，
// 避免两端各写一套 switch。BOOKING_STATUS 仍是「核心四态」入口。
const BOOKING_STATUS_ALL = Object.freeze({
  ...BOOKING_STATUS,
  PENDING: 'booking',                 // 待确认（预订提交未审核）
  COMPLETED: 'completed',             // 已完成
  REJECTED_BOOKING: 'rej-booking',    // 预订被拒
  REJECTED_CANCEL: 'rej-cancelling',  // 取消被拒
  FROZEN: 'frozen',                   // 已冻结
  DELETED: 'deleted'                  // 已删除
});

// 非占位态集合（单一事实来源）。
//
// 与后端 BookingStatus.NON_OCCUPYING = [waiting, cancelled, canceled, rej-booking, frozen] 的关系：
//   前五项严格对齐；'deleted' 是本层**额外的防御项**，后端并不存在这个落库值——
//   后端 BookingStatus.DELETE = 'delete' 只是 updateStatus 的动作值（走 deleteById、不落库），
//   而落库的「已删除」语义由 frozen 承载（见 BookingStatus.FROZEN 的注释）。
//   保留它的理由：万一将来有写路径把 'deleted' 落库，判成「占位」会让席位被永久吃掉，
//   排期一直显示满员、候补永远递补不进来——这正是后端 frozen 当初漏在 NON_OCCUPYING 里踩过的坑。
//   宁可多判一个非占位，也不冒席位泄漏的风险。
//
// 因此这里**不是**与后端逐字相等，而是「后端子集 + deleted 防御项」。改名单时两边都要看。
const NON_OCCUPYING_STATUSES = Object.freeze([
  'waiting', 'cancelled', 'canceled', 'rej-booking', 'frozen', 'deleted'
]);

/* -------------------------------------------------- 状态归一 */

/**
 * 归一化状态：美式/英式拼写统一 + 空值兜底。
 * @param {string|null|undefined} status
 * @returns {string} 归一后的状态串；null/空按 DB 列 NOT NULL DEFAULT 'booked' 兜回 'booked'。
 */
function normalizeBookingStatus(status) {
  if (status === null || status === undefined) return 'booked';
  const s = String(status).trim();
  if (s === '') return 'booked';
  if (s === 'cancelling') return 'canceling';
  if (s === 'canceled') return 'cancelled';
  return s;
}

/* -------------------------------------------------- 占用 / 占位判定 */

/** 该 booking 状态是否占用一个排期席位（纯函数，零 DOM）。 */
function bookingOccupiesSeat(status) {
  return NON_OCCUPYING_STATUSES.indexOf(normalizeBookingStatus(status)) === -1;
}

/** 是否非占位（候补/取消/拒/冻结/删除） */
function isNonOccupying(status) {
  return !bookingOccupiesSeat(status);
}

/* -------------------------------------------------- 单态布尔判定（归一后比较） */

function isWaiting(status) { return normalizeBookingStatus(status) === 'waiting'; }
function isBooked(status) { return normalizeBookingStatus(status) === 'booked'; }
function isPending(status) { return normalizeBookingStatus(status) === 'booking'; }
function isCancelled(status) { return ['cancelled', 'canceled'].indexOf(normalizeBookingStatus(status)) !== -1; }
function isCompleted(status) { return normalizeBookingStatus(status) === 'completed'; }

/* -------------------------------------------------- 转移动作守卫（纯函数） */

/**
 * 是否可「确认」：候补或待确认 → 已确认。
 * 仅做入口校验；真正转正与并发由后端闸门保证。
 */
function canConfirm(status) {
  const s = normalizeBookingStatus(status);
  return s === 'waiting' || s === 'booking';
}

/** 是否可「取消」：已确认或取消待确认 → 已取消 */
function canCancel(status) {
  const s = normalizeBookingStatus(status);
  return s === 'booked' || s === 'canceling';
}

/** 是否可「拒绝」：待确认 / 候补 / 取消待确认 都可被拒 */
function canReject(status) {
  const s = normalizeBookingStatus(status);
  return s === 'waiting' || s === 'booking' || s === 'canceling';
}

/* -------------------------------------------------- 状态 → 展示文案（单一来源，支持两端用字档案） */

/**
 * 文案档案：把「两端用字差异」显式建模成两个受支持的档案，而不是让各端各写一套 switch。
 *
 * 背景：Web 与小程序在这一处的文案**刻意不同**，且该差异已被接受（2026-10-06 拍板：
 * 小程序统一用「预订」，Web/API 维持「预定」不动，含状态「预定待确认」）。
 * 所以这里不是「谁没对齐谁」，而是两个并列的合法口径。
 *
 * 差异清单（web vs default）：
 *   booking         预定待确认 | 待确认
 *   booked          预定已确认 | 已确认
 *   rej-booking     已拒绝预订 | 已拒绝     ← Web 侧原本就用「订」，两端各自沿用，不强行拉平
 *   frozen/deleted  已删除     | 已失效
 * 其余分支（waiting / canceling / cancelled / completed / rej-cancelling）两端完全一致。
 *
 * 为什么用「档案」而不是三个独立参数：这四处分歧不是三个正交维度，
 * 而是「Web 说法」与「小程序说法」两套整体；档案能精确复刻两端现状，不引入猜测规则。
 */
const STATUS_TEXT_PROFILES = {
  // 小程序口径（缺省）。同时是 Web 端 completed 分支缺失时的正确回落值。
  default: {
    booking: '待确认',
    waiting: '候补',
    canceling: '取消待确认',
    booked: '已确认',
    cancelled: '已取消',
    completed: '已完成',
    rejBooking: '已拒绝',
    rejCanceling: '已拒绝取消',
    ended: '已失效'
  },
  // Web 口径：保留「预定」用字（2026-10-06 拍板），ended 用「已删除」。
  web: {
    booking: '预定待确认',
    waiting: '候补',
    canceling: '取消待确认',
    booked: '预定已确认',
    cancelled: '已取消',
    completed: '已完成',
    rejBooking: '已拒绝预订',
    rejCanceling: '已拒绝取消',
    ended: '已删除'
  }
};

/**
 * 状态 → 中文展示文案。
 *
 * @param {string} status
 * @param {Object} [opts] { profile?: 'default' | 'web' }
 *        不传或传未知值一律按 'default'（小程序口径）——保持旧调用点行为不变。
 * @returns {string} 未知状态透传原值；空值回落 '—'。
 *
 * 注：显式调用 web 档案还能顺带修掉 Web 端一个既有缺陷——
 * courseAndBooking.js 的 checkStatus_booking() 没有 completed 分支，
 * 导致「已完成」被原样输出成英文 'completed'；委托后回落 '已完成'。
 */
function bookingStatusText(status, opts) {
  const profile = (opts && opts.profile === 'web')
    ? STATUS_TEXT_PROFILES.web
    : STATUS_TEXT_PROFILES.default;
  switch (normalizeBookingStatus(status)) {
    case 'booking': return profile.booking;
    case 'waiting': return profile.waiting;
    case 'canceling': return profile.canceling;
    case 'booked': return profile.booked;
    case 'cancelled': return profile.cancelled;
    case 'completed': return profile.completed;
    case 'rej-booking': return profile.rejBooking;
    case 'rej-cancelling': return profile.rejCanceling;
    case 'frozen':
    case 'deleted': return profile.ended;
    default: return status || '—';
  }
}

/* -------------------------------------------------- 候补 / 满额判定（纯逻辑） */

// 满额展示文案（与 student-bookingCards.js 的 FULLY_BOOKED_TEXT 对齐，单一来源）。
const FULLY_BOOKED_TEXT = '满额';

/**
 * 剩余员额 → 展示文案（零 DOM 纯函数）。
 * ''/null/undefined/非有限数 一律按「未知」返回空串（不伪装成 0）。
 * 剩余 <= 0 → '满额'；其余显示数字。
 * 注意：满额文案绝不能当数值传给 Number()（会得到 NaN → 误判未满），
 *       需要回读数值时请用 isSiteFull / 数值载体，见 student-bookingCards.js 的 data-remaining 约定。
 */
function formatRemainingSites(remainingSites) {
  if (remainingSites === null || remainingSites === undefined || remainingSites === '') return '';
  const n = Number(remainingSites);
  if (!Number.isFinite(n)) return '';
  return n > 0 ? String(n) : FULLY_BOOKED_TEXT;
}

/** 是否满额（剩余 <= 0）；未知值不视为满（返回 false）。 */
function isSiteFull(remainingSites) {
  const n = Number(remainingSites);
  if (!Number.isFinite(n)) return false;
  return n <= 0;
}

// shared/domain/appointmentState.js
// 跨端共享「课次(appointment)状态」领域层（纯逻辑，零 DOM / 零运行时 API 依赖）。
//
// 这是 P1（Headless 领域层下沉）的一部分：把原本写在
//   - miniprogram/package-student/appointment/appointment.js 的 apptStatusText()
// 里的课次状态 → 文案映射收口为唯一权威源；Web 端「今日课程」(today_course) 后续可对齐复用，
// 消除两端各写一套 switch 的漂移风险。
//
// 【与后端同步】对齐后端 Appointment 状态枚举（active/noted1/noted2/checked-in/completed/absent/
// cancelled/s-cancelling/t-cancelling/t-cancelled/t-reject/changed）。
// 2026-10-28 新增 checked-in（已签到，纯出席事实）与 absent（缺席，终态）。
// 费用口径另见后端 AppointmentStatus#isLessonExempt：**扣减只看有没有请假，与是否签到无关**。
//
// 消费方式：
//   - 小程序端：import { appointmentStatusText } from '../../shared/domain/appointmentState.js'
//   - Web 端：经 P0 构建桥接挂到 window.AppointmentStateDomain（TODO，属 P0-Web 范围）
//   - Node 端：直接 import 做单测（本文件无任何 document/window/fetch 引用）

/* -------------------------------------------------- 状态枚举 */

const APPOINTMENT_STATUS = Object.freeze({
  ACTIVE: 'active',
  NOTED1: 'noted1',
  NOTED2: 'noted2',
  CHECKED_IN: 'checked-in',       // 已签到（学生已进入课堂，纯出席事实，不含费用语义）
  COMPLETED: 'completed',
  ABSENT: 'absent',               // 缺席（课次结束仍未进入课堂；终态，但照扣课时）
  CANCELLED: 'cancelled',
  S_CANCELLING: 's-cancelling',   // 学生取消待确认
  T_CANCELLING: 't-cancelling',   // 教师取消中
  T_CANCELLED: 't-cancelled',     // 教师已取消
  T_REJECT: 't-reject',           // 教师拒绝
  CHANGED: 'changed'              // 已改期
});

// 终态集合（课次已结束，不再可操作）。
// checked-in 刻意不在其中：签到是过程态，后面还要转 completed。
const APPOINTMENT_CLOSED_STATUSES = Object.freeze([
  'completed', 'absent', 'cancelled', 't-cancelled', 'changed'
]);

/* -------------------------------------------------- 状态 → 展示文案（单一来源） */

/**
 * 课次(appointment)状态 → 中文展示文案（单一权威源）。
 *
 * 覆盖：
 *   - 小程序窄集（active/noted/completed/cancelled/s-cancelling/t-cancelling/t-cancelled/t-reject/changed）；
 *   - Web「今日课程」混合表里出现的全部态——课次态之外，同一张表还会混入 booking 态
 *     （booked/waiting/cancelling/canceled/deleted/frozen/reject/rej-booking），
 *     以及排期预览槽的排期态（pending/inactive，由 Web 本地处理，不在此域）。
 * noted1/noted2 合并为「已通知」（两次通知档位，语义一致）。
 * 教师取消相关态（t-cancelling/t-cancelled）带可配置行业词，避免把「教师」硬编码进共享层。
 *
 * @param {string} status
 * @param {Object} [opts] { teacherLabel?: string } 教师/教练等行业词，缺省「教师」
 * @returns {string}
 */
function appointmentStatusText(status, opts) {
  const teacherLabel = (opts && typeof opts.teacherLabel === 'string' && opts.teacherLabel)
    ? opts.teacherLabel : '教师';
  switch (status) {
    case 'active': return '生效';
    case 'noted1':
    case 'noted2': return '已通知';
    case 'checked-in': return '已签到';
    case 'completed': return '已完成';
    case 'absent': return '缺席';
    case 'cancelling':
    case 'canceling':
    case 's-cancelling': return '取消待确认';
    case 'changed': return '已改期';
    case 'cancelled': return '已取消';
    case 't-cancelling': return teacherLabel + '取消中';
    case 't-cancelled': return teacherLabel + '已取消';
    case 't-reject': return '已拒绝';
    // ---- Web 课次/预订混合表（appointmentNotes / 学生端预览）里出现的 booking 态 ----
    case 'booking': return '待确认';
    case 'booked': return '预约已确认';
    case 'waiting': return '候补';
    case 'deleted':
    case 'frozen': return '已删除';
    case 'reject':
    case 'rej-booking': return '已拒绝';
    default: return status || '—';
  }
}

/* -------------------------------------------------- 终态判定（纯函数） */

/** 课次是否已结束（终态），用于过滤「可操作」入口 */
function isAppointmentClosed(status) {
  return APPOINTMENT_CLOSED_STATUSES.indexOf(String(status || '')) !== -1;
}

// 数据脱敏：手机号 / 电子邮箱
// 抽自：
//   - frontend/js/public/api.js 的 maskPhone / maskEmail（Web 端唯一实现）
//   - miniprogram/shared/format.js 的 maskPhone / maskEmail（手迁副本，已改为 re-export 本模块）
// 消费：列表页用 maskPhone / maskEmail 渲染手机/邮箱；后台编辑回填必须走原始值缓存，
//       绝不能把脱敏串（如 138****5678）写回数据库。
// 纯函数、零 DOM、零小程序 API。Node 下可直接 import 做单测。
// Web 端经 P0 构建桥接后可挂 window.MaskDomain（当前为 P0-Web 阻塞，未接）。

/** 手机号脱敏：11 位保留前3后4；其余保留首尾、中间用 * 代替（≤4 位全盘星） */
function maskPhone(phone) {
  if (phone == null) return '';
  const s = String(phone).trim();
  const L = s.length;
  if (L === 0) return '';
  if (L === 11) return s.substring(0, 3) + '****' + s.substring(7);
  if (L <= 4) return '*'.repeat(L);
  return s.substring(0, 1) + '*'.repeat(L - 2) + s.substring(L - 1);
}

/** 电子邮箱脱敏：仅遮蔽 @ 之前部分，保留域名与前后缀以提高辨识度。
 *  本地部分规则：
 *   - 长度 ≤ 1：全盘 *            （如 a@b.cn      → *@b.cn）
 *   - 长度 = 2：保留首字符 + 1*   （如 ab@c        → a*@c）
 *   - 长度 3~4：保留首字符，其余 *（如 abc@x → a**@x，abcd@x → a***@x）
 *   - 长度 ≥ 5：保留前 2 + 后 2，中间最多 4 个 *（如 zhangsan@example.com → zh****an@example.com）
 *  无 @ 的串原样返回（非邮箱，不脱敏）。 */
function maskEmail(email) {
  if (email == null) return '';
  const s = String(email).trim();
  if (s.length === 0) return '';
  const atIdx = s.indexOf('@');
  if (atIdx < 0) return s;                       // 无 @ 视为非邮箱，原样返回
  const local = s.substring(0, atIdx);
  const domain = s.substring(atIdx);             // 含 @，整段保留
  const L = local.length;
  let masked;
  if (L <= 1) {
    masked = '*';
  } else if (L <= 4) {
    masked = local.charAt(0) + '*'.repeat(Math.max(1, L - 1));
  } else {
    const stars = '*'.repeat(Math.min(4, L - 4));
    masked = local.substring(0, 2) + stars + local.substring(L - 2);
  }
  return masked + domain;
}

// 时区 / 日历装配：日期时间格式化与解析（零 DOM、零小程序 API，纯函数）
// 抽自 Web 端多处散落实现：
//   - frontend/js/public/auditLog.js:144 formatTime       → String(t).replace('T',' ').substring(0,19)
//   - frontend/js/public/appointmentNotes.js:726 / messages-inbox.js:322 / datamaintain_delete.js / platform-admin-tenant.js
//     各处 String(x).replace('T',' ').slice(0,16) 的重复写法
//   - frontend/js/admin-notify-rule.js:95 notifyFmtDateTime / :101 notifyParseLocal（本地时间解析）
//   - frontend/js/public/courseAndBooking.js:753/1052 记载的时区坑：new Date('yyyy-MM-dd') 因时区偏移会少一天
//   - miniprogram/package-student/appointment/appointment.js:8 fmtTime → replace('T',' ').slice(0,16)
// 统一为本模块后，两端共用同一套时区安全逻辑，消除漂移。
// Node 下可直接 import 做单测。

const PAD = (n) => (n < 10 ? '0' + n : '' + n);

/** 格式化日期时间为 'yyyy-MM-dd HH:mm[:ss]'。
 *  iso 可为 'yyyy-MM-ddTHH:mm:ss' / 'yyyy-MM-dd HH:mm:ss' / yyyy-MM-ddTHH:mm 等。
 *  withSeconds=false 时截到分钟（yyyy-MM-dd HH:mm）。 */
function formatDateTime(iso, withSeconds = true) {
  if (iso == null) return '';
  const s = String(iso).replace('T', ' ');
  if (!s) return '';
  return withSeconds ? s.substring(0, 19) : s.substring(0, 16);
}

/** 截取日期部分 'yyyy-MM-dd'（无效返回 ''）。 */
function formatDate(iso) {
  if (iso == null) return '';
  const s = String(iso);
  return /^\d{4}-\d{1,2}-\d{1,2}/.test(s) ? s.substring(0, 10) : '';
}

/** 解析 'yyyy-MM-dd' 为本地 Date，**规避 new Date('yyyy-MM-dd') 的 UTC/时区偏移**（用年/月/日构造）。无效返回 null。 */
function parseLocalDate(dateStr) {
  if (!dateStr) return null;
  const m = String(dateStr).match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (!m) return null;
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return isNaN(d.getTime()) ? null : d;
}

/** 解析 'yyyy-MM-ddTHH:mm' / 'yyyy-MM-dd HH:mm' 为本地时间 Date（无效返回 null）。
 *  用于把表单/接口字符串还原成 Date 做比较。 */
function parseLocalDateTime(text) {
  if (!text) return null;
  const d = new Date(String(text).replace(' ', 'T'));
  return isNaN(d.getTime()) ? null : d;
}

/** 取中文星期（周一…周日）。
 *  input 可为 Date 或 'yyyy-MM-dd' 字符串（字符串走 parseLocalDate 规避时区偏移）。无有效值返回 ''。 */
function weekdayCN(input) {
  if (input instanceof Date) {
    return isNaN(input.getTime()) ? '' : ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][input.getDay()];
  }
  const d = parseLocalDate(input);
  return d ? ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][d.getDay()] : '';
}

/** Date → 'yyyy-MM-ddTHH:mm'（供 <input type="datetime-local"> 回填）。无效返回 ''。 */
function toDateTimeLocalValue(date) {
  if (!(date instanceof Date) || isNaN(date.getTime())) return '';
  return date.getFullYear() + '-' + PAD(date.getMonth() + 1) + '-' + PAD(date.getDate()) +
    'T' + PAD(date.getHours()) + ':' + PAD(date.getMinutes());
}

// ============================================================
// 课次时间 UTC 化（2026-10-08，见 doc-develop/课次时间UTC化改造方案.md）
//
// 口径：后端 appointment 起一律返回 UTC。页面要显示"人能对上的墙上时间"，
// 由前端按用户浏览器时区渲染。后端也可按 userTimeZone 直接转好，
// 两者都支持，本模块负责后者缺失时的前端兜底。
//
// ⚠️ 转换必须用 Intl.DateTimeFormat，不能手算偏移量：
//    手算在夏令时切换日会错 1 小时（America/Edmonton 每年 3 月、11 月各切一次）。
// ============================================================

/** 取用户浏览器时区 ID，如 'Asia/Shanghai'；不可用时返回 'UTC'。 */
function nowUserTz() {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return (tz && String(tz).trim()) ? tz : 'UTC';
  } catch (e) {
    return 'UTC';
  }
}

/**
 * 校验时区串是否为可用的 IANA ID。
 *
 * ⚠️ 为什么必须显式校验而不能靠 Intl 抛错：**Intl 认得三字母缩写**。
 *    实测 'CST' 不抛错，而是静默解析成 UTC-6（美洲中部），于是用户看到的
 *    时间平白差 14 小时，且没有任何报错 —— 这比抛错危险得多。
 *    'GMT+8' 这类反而不被支持会抛错。两者行为不一致，只能自己把关。
 *
 * 判据：ZoneId.of() 接受的形式是 `区域/城市`（含斜杠）或 'UTC'。
 */
function isValidZone(tz) {
  if (!tz || !String(tz).trim()) return false;
  const s = String(tz).trim();
  if (s === 'UTC' || s === 'GMT') return true;
  // 必须是 Region/City 形态，且两段都不能为空
  return /^[A-Za-z][A-Za-z0-9_+-]*\/[A-Za-z0-9_+-]+$/.test(s);
}

/**
 * 把 UTC 时间串转成指定时区的显示串。
 * @param iso      'yyyy-MM-ddTHH:mm:ss' / 'yyyy-MM-dd HH:mm:ss'（**按 UTC 解读**）
 * @param timeZone 目标时区，省略则用用户浏览器时区
 * @param withSeconds 是否带秒，默认不带（列表页够用）
 * @returns 'yyyy-MM-dd HH:mm[:ss]'；无法解析返回 ''
 *
 * 用法约定：**不要**对已是本地时间的串调用本函数（会二次偏移）。
 * 判断依据：后端明确说"这是 UTC"时才转。
 */
function utcToZoned(iso, timeZone, withSeconds = false) {
  if (iso == null || iso === '') return '';
  const s = String(iso).trim();
  if (!s) return '';

  // 关键：裸串必须补 Z，否则 new Date() 会按浏览器本地时区解读，偏移一次。
  // 已带时区信息（Z 或 ±HH:mm）的原样使用。
  let normalized = s.replace(' ', 'T');
  if (!/([Zz]|[+-]\d{2}:?\d{2})$/.test(normalized)) {
    normalized += 'Z';
  }

  const date = new Date(normalized);
  if (isNaN(date.getTime())) return '';

  const tz = (timeZone && isValidZone(timeZone)) ? String(timeZone).trim() : nowUserTz();
  try {
    const parts = new Intl.DateTimeFormat('sv-SE', {
      timeZone: tz,
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit',
      second: withSeconds ? '2-digit' : undefined,
      hour12: false
    }).formatToParts(date);

    const get = (type) => {
      const hit = parts.find(p => p.type === type);
      return hit ? hit.value : '';
    };
    // Intl 在 hour12:false 下可能给 "24:00"（午夜），归一到 "00:00"
    const hour = get('hour') === '24' ? '00' : get('hour');

    const datePart = get('year') + '-' + get('month') + '-' + get('day');
    const timePart = hour + ':' + get('minute') + (withSeconds ? ':' + get('second') : '');
    return datePart + ' ' + timePart;
  } catch (e) {
    // 时区串非法（如 'CST'）：退回 UTC 展示而不是抛错，页面不至于整块崩
    return utcToZoned(iso, 'UTC', withSeconds);
  }
}

/** utcToZoned + 中文星期，如 '2026-09-07 09:00 周一'。 */
function utcToZonedWithWeekday(iso, timeZone) {
  const base = utcToZoned(iso, timeZone, false);
  if (!base) return '';
  const d = parseLocalDate(base.substring(0, 10));
  const wd = d ? ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][d.getDay()] : '';
  return wd ? base + ' ' + wd : base;
}

// HTTP / 业务错误码 → 统一可读性文案 + 类型判定（纯逻辑，不含 toast/showModal）
// 抽自：
//   - frontend/js/public/utility_request.js 响应拦截（res.code 200/401/403/其他）+ 错误拦截（ECONNABORTED 超时 / 无 response 网络不可达 / http 状态）
//   - frontend/js/public/api.js 的 401/403 注释段
// 消费：请求适配层 / 页面 catch 用 resolveRequestError(err).message 取友好文案（展示交给 ui 层）。
// 纯函数、零 DOM。Node 下可直接 import 做单测。
// Web 端已通过 window.ErrorCodeDomain 挂载（bridge-exports.json 登记，utility_request.js 在调）。

const RESULT_OK = 200;

/**
 * 需要人机验证（2026-10-22 P0，登录风控频率闸）。
 *
 * 与服务端 {@code Result.CODE_NEED_CHALLENGE} 对齐，走 HTTP 200 + body.code，
 * 刻意不进 ResultHttpStatusAdvice 的 400/404/409/500 映射表——否则 axios 会把它当
 * HTTP 错误走 error 拦截器，与 401 刷新链路混在一起。
 *
 * 这里定义一次、两端共用：Web 弹 DOM 滑块、小程序弹 canvas 滑块，
 * 但"这是挑战、不是错误"这个语义只能有一个出处，否则必然出现
 * "Web 弹红字报错、小程序被 silent catch 吞掉"两种表述。
 */
const RESULT_NEED_CHALLENGE = 1002;

/** 解析后端统一响应体 { code, message, msg, data }（即 response.data）。
 *  返回 { type, message, data, code }：
 *   - ok          code===200，data 透传
 *   - challenge   code===1002，需人机验证；data 为挑战素材（challengeId/拼图），可能为空
 *   - unauthorized code===401，message 缺省 '登录已过期'
 *   - forbidden   code===403，message 缺省 '无权限访问该资源'
 *   - biz         其它业务错误，message 缺省 '操作失败'
 *  message 优先取 message 字段，其次 msg（对齐 utility_request.js 的 res.message || res.msg）。 */
function resolveResult(res) {
  if (!res || typeof res !== 'object') {
    return { type: 'biz', message: '响应格式异常', data: undefined, code: undefined };
  }
  const code = res.code;
  const message = res.message || res.msg || '';
  if (code === RESULT_OK) return { type: 'ok', message: '', data: res.data, code };
  if (code === RESULT_NEED_CHALLENGE) {
    return { type: 'challenge', message: message || '请完成安全验证', data: res.data, code };
  }
  if (code === 401) return { type: 'unauthorized', message: message || '登录已过期', data: undefined, code };
  if (code === 403) return { type: 'forbidden', message: message || '无权限访问该资源', data: undefined, code };
  return { type: 'biz', message: message || '操作失败', data: undefined, code };
}

/** 解析 axios / wx.request 的错误对象。
 *  返回 { type, message, status }：
 *   - timeout  错误码 ECONNABORTED 且 message 含 'timeout'
 *   - network  无 error.response（网络不可达 / 断网）
 *   - http     其它 HTTP 错误，含 response.status
 *  文案与 utility_request.js 原拦截器保持一致。 */
function resolveRequestError(err) {
  if (!err) return { type: 'network', message: '网络连接失败，请检查网络', status: undefined };
  if (err.code === 'ECONNABORTED' && typeof err.message === 'string' && err.message.includes('timeout')) {
    return { type: 'timeout', message: '请求超时，请稍后重试', status: undefined };
  }
  if (!err.response) return { type: 'network', message: '网络连接失败，请检查网络', status: undefined };
  const status = err.response.status;
  return { type: 'http', message: '服务异常（HTTP ' + status + '）', status };
}

/** 取错误友好文案（页面 catch 直接用的便捷函数）。 */
function errorMessage(err) {
  return resolveRequestError(err).message;
}

// 消息中心展示映射：编码 → 文案（零 DOM、零小程序 API、纯函数）
// 抽自两端各自一份的重复实现：
//   - miniprogram/core/message.js（SENDER_TEXT / PRIORITY_TEXT / CATEGORY_DICT + 四个映射函数）
//   - frontend/js/messages-inbox.js（列表行、已发行、详情弹层直接贴裸编码）
// 统一为本模块后，Web 端经 P0 桥接挂 window.MessageDomain，小程序端 core/message.js 委托同一份，
// 新增优先级档位 / 发送者类型时只需改这里（否则两端必然漂移）。
//
// 背景：message-service 库里存的都是**编码**——
//   · priority：HIGH / MEDIUM / LOW（msg_message.priority）
//   · senderType：teacher / admin / platform_admin / student / system
//   · categoryCode：租户或平台在「消息分类」里自定义的编码，展示名在 msg_category.category_name
// 界面上不允许出现 categoryCode / HIGH 这类裸编码，一律过下面的映射函数。

/** 优先级编码 → 文案 */
const PRIORITY_TEXT = { HIGH: '高', MEDIUM: '中', LOW: '低' };

/** 发送者类型编码 → 文案 */
const SENDER_TYPE_TEXT = {
  teacher: '教师',
  admin: '管理员',
  platform_admin: '平台管理员',
  student: '学生',
  system: '系统'
};

// 分类编码 → 名称字典（canonical 形状：{ code, name }）。由分类树填充。
// 收件箱列表/详情后端会顺带回填 categoryName；「已发 / 管理」列表与投递详情**只给 categoryCode**，
// 所以必须留一份本地字典兜底，否则这两处只能显示编码。
let CATEGORY_DICT = Object.create(null);

/**
 * 用分类列表刷新字典（幂等）。
 * 入参为 canonical 形状：[{ code, name }]；后端原始树请先过 categoryListFromTree()。
 * @returns {Object} 刷新后的字典副本
 */
function setCategoryDict(list) {
  const dict = Object.create(null);
  (list || []).forEach((c) => {
    if (c && c.code) dict[c.code] = c.name || c.code;
  });
  CATEGORY_DICT = dict;
  return Object.assign({}, dict);
}

/** 当前分类字典（只读用途；需要一份普通对象时用返回副本） */
function getCategoryDict() {
  return Object.assign({}, CATEGORY_DICT);
}

/** 分类展示文案：后端名称 → 本地字典 → 「未分类」（有编码但查不到名称）；无编码返回空（不显示标签） */
function categoryText(code, name) {
  if (name) return name;
  if (!code) return '';
  return CATEGORY_DICT[code] || '未分类';
}

/**
 * 后端分类树/列表 → canonical [{ code, name, level }]。
 * 兼容后端两种字段名（categoryCode/categoryName 与 code/name）与嵌套 children；
 * CategoryController.tree() 当前返回扁平列表，children 分支是防御性的。
 */
function categoryListFromTree(items) {
  const out = [];
  (function walk(arr) {
    (arr || []).forEach((c) => {
      if (!c) return;
      const code = c.categoryCode || c.code;
      const name = c.categoryName || c.name;
      if (code) out.push({ code: code, name: name || code, level: c.categoryLevel || c.level || 1 });
      if (Array.isArray(c.children)) walk(c.children);
    });
  })(items);
  return out;
}

/**
 * 收集分类编码白名单（发送前前端预校验用）。
 * 兼容原始树与 canonical 列表，递归取 小写编码 → true。
 */
function collectCategoryCodes(items) {
  const valid = Object.create(null);
  (function walk(arr) {
    (arr || []).forEach((c) => {
      if (!c) return;
      const code = c.categoryCode || c.code;
      if (code) valid[String(code).toLowerCase()] = true;
      if (Array.isArray(c.children)) walk(c.children);
    });
  })(items);
  return Object.assign({}, valid);
}

/** 优先级编码（供样式类名 pri-XXX / msg-pri.XXX 用，不参与展示） */
function priorityCode(code) {
  return code ? String(code).toUpperCase() : '';
}

/** 优先级展示文案：空值返回空，未知编码原样透出（便于排查新增档位），否则 HIGH/MEDIUM/LOW → 高/中/低 */
function priorityText(code) {
  if (code === null || code === undefined || code === '') return '';
  const key = String(code).toUpperCase();
  return PRIORITY_TEXT[key] || String(code);
}

/** 发送者类型展示文案：空值返回空，未知编码原样透出 */
function senderTypeText(type) {
  if (!type) return '';
  return SENDER_TYPE_TEXT[type] || String(type);
}

/* ==================== 消息状态（发送台账：「已发」/「消息管理」列表与详情用） ==================== */

/**
 * 消息状态编码 → 文案（msg_message.status）。
 *
 * `withdrawn` 是**历史值**，与 `recalled` 同义（都是「已收回」）：
 *   · 建表注释里声明的词汇表是 `sent/withdrawn`（原文「已撤回」，注释本身已被 GBK 误读成乱码）；
 *   · 而代码从第一版提交起只写 `sent`/`recalled`/`partial_recalled`（全历史 .java 中 grep `withdrawn` 命中 0）；
 *   · 库里现存 3 行 `withdrawn` 均为 2026-09-05 的早期数据（send_time = update_time，从未执行过撤回动作）。
 * 故此处按「同义别名」归一，而不是当脏数据丢弃 —— 界面上必须给出中文，不能漏出裸英文。
 */
const MESSAGE_STATUS_TEXT = {
  sent: '已发送',
  recalled: '已收回',
  partial_recalled: '部分收回',
  withdrawn: '已收回',
};

/** 消息状态编码 → 文案；未知编码原样透出，便于发现新增档位 */
function messageStatusText(status) {
  if (!status) return '';
  return MESSAGE_STATUS_TEXT[status] || String(status);
}

/* ==================== 投递 / 接收人状态（「已发」详情的接收人列表用） ==================== */

/** 投递状态编码 → 文案（msg_delivery.delivery_status） */
const DELIVERY_STATUS_TEXT = { 0: '未投递', 1: '已投递', 2: '已确认接收', 3: '投递失败' };

/** 投递状态编码 → 文案；未知编码原样透出，便于排查新增档位 */
function deliveryStatusText(code) {
  if (code === null || code === undefined || code === '') return '';
  return DELIVERY_STATUS_TEXT[Number(code)] || String(code);
}

/**
 * 接收人行的状态标签：把「投递状态」与「收件箱副本状态」合并成一个人类可读的词。
 *
 * 判定优先级（自上而下，命中即返回）：
 *   ① isDeleted=1 → 已撤回：收回（withdraw）会把**未读**副本置为已删除，这是用户视角的「撤回」
 *   ② isRead=1   → 已读（阅读时间另行展示 readTime）
 *   ③ deliveryStatus=3 → 投递失败
 *   ④ deliveryStatus=0 → 未投递（尚未落库到对方收件箱）
 *   ⑤ 其余 → 未读
 *
 * 返回 { text, cls }：text 直接展示，cls 供样式类（rec-read / rec-unread / rec-failed / rec-pending / rec-revoked）；
 * 状态文案一律走本函数，界面上不出现裸 deliveryStatus 数字。
 */
function recipientStateText(row) {
  const r = row || {};
  if (r.isDeleted) return { text: '已撤回', cls: 'revoked' };
  if (r.isRead) return { text: '已读', cls: 'read' };
  const st = (r.deliveryStatus === null || r.deliveryStatus === undefined) ? null : Number(r.deliveryStatus);
  if (st === 3) return { text: '投递失败', cls: 'failed' };
  if (st === 0) return { text: '未投递', cls: 'pending' };
  return { text: '未读', cls: 'unread' };
}

/* ==================== 发送方租户（平台管理员识别「哪家租户发来的」） ==================== */

/**
 * 租户ID → 公司名（org_name）字典。
 *
 * 用途唯一：**平台管理员**看消息详情时，消息来自哪个租户需要落到公司名。
 * 数据源是主系统的 GET /api/v1/tenant/list（PLATFORM_ONLY，返回 [{id, tenantCode, orgName}]）；
 * message-service（消息库）是独立库，拿不到 sys_tenant，故只能由调用方拉全量后灌进这里。
 *
 * 为什么不能按 tenantId 逐个查 /tenant/{id}：一页 N 条就是 N 次请求。
 * 租户总量是「几十」量级，拉全量建映射更划算（platform-admin-package.js 已是这个做法）。
 */
let TENANT_DICT = {};

/** 用 /tenant/list 结果刷新字典；兼容 {id,...} 与 {tenantId,...} 两种键名 */
function setTenantDict(list) {
  const dict = {};
  (list || []).forEach((t) => {
    if (!t) return;
    const id = (t.id !== undefined && t.id !== null) ? t.id : t.tenantId;
    const name = t.orgName || t.name || '';
    if (id !== undefined && id !== null && String(id) !== '' && name) dict[String(id)] = name;
  });
  TENANT_DICT = dict;
  return dict;
}

/** 当前字典（只读用途，便于测试与排查） */
function getTenantDict() {
  return TENANT_DICT;
}

/**
 * 发送方租户展示文案。
 *
 * 刻意**没有兜底文案**：tenantId 为空/≤0（消息由平台自身发出）、或字典里查不到（租户已删、字典未到位）
 * 时一律返回空串，由调用方省略整段「发送方租户：…」，界面上不出现「未知租户」「租户 12」这类降级文案
 * ——平台视角下「没有租户」本身就是有效语义（平台内部消息）。
 */
function tenantText(id) {
  if (id === null || id === undefined || id === '') return '';
  const n = Number(id);
  if (!isFinite(n) || n <= 0) return '';
  return TENANT_DICT[String(id)] || '';
}

// 课时账本展示映射（零 DOM、零小程序 API、纯函数）
//
// 背景（2026-10-28）：课时扣减落地后，账本里存的是**编码与原始数值**：
//   · source：classroom / leave / manual / grant（英文枚举）
//   · changeLessons：-1.00 / 2.00（BigDecimal 序列化，可能带多余小数位）
//   · remainingLessons：允许负数（欠课时）
// 界面上不允许出现 `classroom` 这类裸编码，也不适合直接显示 `-1.00`。
// 两端（Web 学生端「我的课时」、小程序）共用本模块，避免各写一套映射必然漂移。

/** 流水来源编码 → 文案 */
const LESSON_FLOW_SOURCE_TEXT = {
  classroom: '课堂扣减',
  leave: '请假退回',
  manual: '人工调整',
  grant: '课时充值'
};

/** 来源文案（未知编码回退原值，便于发现后端新增了没登记的来源） */
function lessonSourceText(source) {
  if (!source) return '课时变动';
  return LESSON_FLOW_SOURCE_TEXT[source] || String(source);
}

/**
 * 课时数值格式化：去掉无意义的尾随 0（1.00 → 1、0.50 → 0.5），保留小数最多 2 位。
 * 非数值一律返回 '0'——展示层不该因为一个脏值整页崩掉。
 */
function formatLessonAmount(value) {
  const n = Number(value);
  if (!isFinite(n)) return '0';
  return String(parseFloat(n.toFixed(2)));
}

/**
 * 变动课时的带符号文案：消耗为负数，所以 `-1` → '-1'、`2` → '+2'。
 * 不用 Unicode 减号（−）：复制到 Excel/客服话术里会变成不可见字符。
 */
function lessonChangeText(value) {
  const n = Number(value);
  if (!isFinite(n) || n === 0) return '0';
  const s = formatLessonAmount(Math.abs(n));
  return n > 0 ? '+' + s : '-' + s;
}

/**
 * 流水行标题：优先「课程名 · 第N课次」，缺课程名时退回来源文案。
 *
 * 为什么可能缺课程名：courseName 要经 booking → course_schedule 反查，
 * 排期被删除或历史脏数据时 join 不到，此时不能显示 "undefined"。
 */
function lessonRowTitle(flow) {
  const f = flow || {};
  const name = f.courseName ? String(f.courseName) : '';
  const idx = Number(f.classIndex);
  const idxText = isFinite(idx) && idx > 0 ? '第' + idx + '课次' : '';
  if (name && idxText) return name + ' · ' + idxText;
  if (name) return name;
  if (idxText) return idxText;
  return lessonSourceText(f.source);
}

/**
 * 课时账户色调：owed（欠课时）/ empty（已用完）/ normal（正常）。
 * 只返回语义，颜色交给各端 CSS——Web 深色主题与小程序主题取值不同。
 */
function lessonBalanceTone(balance) {
  const b = balance || {};
  if (b.owed) return 'owed';
  const n = Number(b.remainingLessons);
  if (isFinite(n) && n === 0) return 'empty';
  return 'normal';
}

// 网络适配层（单一权威源，零平台特定副作用）。
// 运行时自动探测：小程序用 wx.request；Web 用 fetch。
// 仅暴露「可移植的传输原语」transport —— 401 刷新 / Bearer 注入 / 解包 / 错误 toast
// 等「应用级」逻辑由各端 core 层（mp core/request.js、Web utility_request.js）在其上叠加，
// 不塞进共享层，避免平台耦合。
//
// transport(config) -> Promise<{ statusCode, data, header }>
//   config: { url, method, data, header }
// 约定：统一返回 statusCode（mp 原生 statusCode / Web fetch res.status），
//       使调用方（core/request.js）无需区分两端。

function isMp() {
  return typeof wx !== 'undefined' && typeof wx.request === 'function';
}
function getWin() {
  return (typeof window !== 'undefined') ? window : null;
}

function mpRequest(config) {
  return new Promise((resolve, reject) => {
    wx.request({
      url: config.url,
      method: (config.method || 'GET').toUpperCase(),
      data: config.data,
      header: config.header || {},
      success: (res) => resolve({ statusCode: res.statusCode, data: res.data, header: res.header || {} }),
      fail: (err) => reject(err)
    });
  });
}

async function webRequest(config) {
  const w = getWin();
  if (!w || typeof w.fetch !== 'function') throw new Error('no transport available (need wx.request or fetch)');
  const method = (config.method || 'GET').toUpperCase();
  const init = { method, headers: config.header || {} };
  if (config.data !== undefined && config.data !== null && method !== 'GET' && method !== 'HEAD') {
    init.body = (typeof config.data === 'string') ? config.data : JSON.stringify(config.data);
  }
  const res = await w.fetch(config.url, init);
  let data = null;
  try {
    const ct = (res.headers && typeof res.headers.get === 'function') ? (res.headers.get('content-type') || '') : '';
    data = ct.indexOf('application/json') >= 0 ? await res.json() : await res.text();
  } catch (e) {
    try { data = await res.text(); } catch (_) { /* ignore */ }
  }
  return { statusCode: res.status, data, header: {} };
}

function transport(config) {
  if (isMp()) return mpRequest(config);
  return webRequest(config);
}



// 存储适配层（单一权威源，零平台特定副作用）。
// 运行时自动探测：小程序用 wx.getStorageSync/setStorageSync；Web 用 localStorage。
// 接口与浏览器 localStorage 对齐：get/set/remove/clear。
// 约定：写入时 Web 端非字符串值自动 JSON.stringify（localStorage 只收字符串）；
//       读出时两端均原样返回（mp 保留类型，Web 返回字符串由调用方按需 JSON.parse）。
// 调用方（如 getSession）已对「字符串/对象」两种形态做兼容，故本层不做二次序列化。

function isMp() {
  return typeof wx !== 'undefined' && typeof wx.getStorageSync === 'function';
}
function getWin() {
  return (typeof window !== 'undefined') ? window : null;
}

const storage = {
  get(key) {
    if (isMp()) { try { return wx.getStorageSync(key); } catch (e) { return ''; } }
    const w = getWin();
    if (w && w.localStorage) { try { return w.localStorage.getItem(key); } catch (e) { return ''; } }
    return '';
  },
  set(key, val) {
    const v = (typeof val === 'string') ? val : JSON.stringify(val);
    if (isMp()) { try { wx.setStorageSync(key, val); } catch (e) { /* ignore */ } return; }
    const w = getWin();
    if (w && w.localStorage) { try { w.localStorage.setItem(key, v); } catch (e) { /* ignore */ } }
  },
  remove(key) {
    if (isMp()) { try { wx.removeStorageSync(key); } catch (e) { /* ignore */ } return; }
    const w = getWin();
    if (w && w.localStorage) { try { w.localStorage.removeItem(key); } catch (e) { /* ignore */ } }
  },
  clear() {
    if (isMp()) { try { wx.clearStorageSync(); } catch (e) { /* ignore */ } return; }
    const w = getWin();
    if (w && w.localStorage) { try { w.localStorage.clear(); } catch (e) { /* ignore */ } }
  }
};



// 弹窗/对话框适配层（单一权威源，零平台特定副作用）。
// 运行时自动探测：小程序用 wx.showModal；Web 用 window.alert/confirm/prompt。
// 统一为 Promise 接口，使两端调用方（包括共享业务代码）写法一致。
//
// 关键差异：小程序无原生 prompt（无法在 showModal 内输入文本）。
// 故 prompt 在 mp 端默认拒绝，并提示业务页「注入自定义输入组件解析器」——
// 即「重设计输入流」：把文本输入下沉到页面级 WXML 输入框，再经 setPromptResolver 回灌。
// 这是 mp 与 Web 唯一不能逐字对齐的适配点，已在设计上显式暴露而非静默降级。

function isMp() {
  return typeof wx !== 'undefined' && typeof wx.showModal === 'function';
}
function getWin() {
  return (typeof window !== 'undefined') ? window : null;
}

let promptResolver = null;
function setPromptResolver(fn) {
  promptResolver = (typeof fn === 'function') ? fn : null;
}

// alert：仅告知，无返回值（resolve 当点击确定）
function alert(message, opts) {
  opts = opts || {};
  if (isMp()) {
    return new Promise((resolve) => {
      wx.showModal({
        title: opts.title || '提示',
        content: String(message == null ? '' : message),
        showCancel: false,
        confirmText: opts.confirmText || '确定',
        success: () => resolve(),
        fail: () => resolve()
      });
    });
  }
  const w = getWin();
  if (w) { w.alert(message); return Promise.resolve(); }
  return Promise.resolve();
}

// confirm：返回 Promise<boolean>
function confirm(message, opts) {
  opts = opts || {};
  if (isMp()) {
    return new Promise((resolve) => {
      wx.showModal({
        title: opts.title || '提示',
        content: String(message == null ? '' : message),
        showCancel: opts.showCancel !== false,
        confirmText: opts.confirmText || '确定',
        cancelText: opts.cancelText || '取消',
        success: (res) => resolve(!!res.confirm),
        fail: () => resolve(false)
      });
    });
  }
  const w = getWin();
  if (w && typeof w.confirm === 'function') return Promise.resolve(w.confirm(message));
  return Promise.resolve(false);
}

// prompt：返回 Promise<string|null>（取消/不支持时为 null）
function prompt(message, defaultValue, opts) {
  opts = opts || {};
  if (isMp()) {
    if (promptResolver) return Promise.resolve(promptResolver(message, defaultValue, opts));
    return Promise.reject(new Error('小程序端暂不支持原生 prompt：请使用页面内输入框组件，并调用 setPromptResolver 注入解析器'));
  }
  const w = getWin();
  if (w && typeof w.prompt === 'function') return Promise.resolve(w.prompt(message, defaultValue));
  return Promise.resolve(null);
}



// 路由适配层（单一权威源，零平台特定副作用）。
// 统一接口：setRoutes / to / replace / back / current / parseQuery / openUrl
// 运行时自动探测：小程序用 wx.navigateTo/redirectTo/navigateBack；Web 用 location/history。
//
// 约定：
//   - 通过 setRoutes(name -> { web, mp }) 注册「命名路由」；to('login', {x:1}) 两端各走对应路径并拼参。
//   - 未注册的 name 原样当作路径（to('booking.html') 在 Web 即跳 booking.html，mp 即跳该页面路径）。
//   - openUrl(url) 直接吃一个已拼好的路径/URL，不做路由表解析（两端各自 navigateTo / location.href）。
// 视图层（具体哪个按钮跳哪页）属 Decision 3 允许不一致的范围；本层只收敛「跳转原语」接口。

function isMp() {
  return typeof wx !== 'undefined' && typeof wx.navigateTo === 'function';
}
function getWin() {
  return (typeof window !== 'undefined') ? window : null;
}

let routes = {};

function setRoutes(map) {
  routes = map || {};
}

function buildUrl(target, params) {
  let url = target;
  const r = routes[target];
  if (r) {
    url = isMp() ? (r.mp || r.web) : (r.web || r.mp);
  }
  if (params && typeof params === 'object') {
    const qs = Object.keys(params)
      .filter(k => params[k] !== undefined && params[k] !== null)
      .map(k => encodeURIComponent(k) + '=' + encodeURIComponent(params[k]))
      .join('&');
    if (qs) url += (url.indexOf('?') >= 0 ? '&' : '?') + qs;
  }
  return url;
}

function to(name, params) {
  const url = buildUrl(name, params);
  if (isMp()) {
    return new Promise((resolve, reject) => {
      wx.navigateTo({ url, success: () => resolve(), fail: (e) => reject(e) });
    });
  }
  const w = getWin();
  if (w) { w.location.href = url; return Promise.resolve(); }
  return Promise.resolve();
}

function replace(name, params) {
  const url = buildUrl(name, params);
  if (isMp()) {
    return new Promise((resolve, reject) => {
      wx.redirectTo({ url, success: () => resolve(), fail: (e) => reject(e) });
    });
  }
  const w = getWin();
  if (w) { w.location.replace(url); return Promise.resolve(); }
  return Promise.resolve();
}

function back(delta) {
  if (isMp()) {
    try { wx.navigateBack({ delta: delta || 1 }); } catch (e) { /* ignore */ }
    return Promise.resolve();
  }
  const w = getWin();
  if (w && w.history) { w.history.back(); }
  return Promise.resolve();
}

function current() {
  if (isMp()) {
    try {
      const pages = (typeof getCurrentPages === 'function') ? getCurrentPages() : [];
      const p = pages[pages.length - 1];
      return { path: p ? p.route : '', query: p ? (p.options || {}) : {}, platform: 'mp' };
    } catch (e) {
      return { path: '', query: {}, platform: 'mp' };
    }
  }
  const w = getWin();
  if (w && w.location) {
    return { path: w.location.pathname, query: parseQuery(w.location.search), platform: 'web' };
  }
  return { path: '', query: {}, platform: 'unknown' };
}

function parseQuery(search) {
  const q = {};
  if (!search) return q;
  const s = String(search).replace(/^[?#]/, '');
  if (!s) return q;
  s.split('&').forEach((pair) => {
    if (!pair) return;
    const idx = pair.indexOf('=');
    const k = idx >= 0 ? pair.slice(0, idx) : pair;
    const v = idx >= 0 ? pair.slice(idx + 1) : '';
    try { q[decodeURIComponent(k)] = decodeURIComponent(v); } catch (e) { q[k] = v; }
  });
  return q;
}

function openUrl(url) {
  if (isMp()) {
    return new Promise((resolve, reject) => {
      wx.navigateTo({ url, success: () => resolve(), fail: (e) => reject(e) });
    });
  }
  const w = getWin();
  if (w) { w.location.href = url; return Promise.resolve(); }
  return Promise.resolve();
}




